                } else {
                        r_strbuf_append (buf, "[]");
                }
        } else {
                int len = 4;
                if (flags) {
                        // const char *flag_string = r_bin_get_meth_flag_string (flag, true);
                        char *flag_string = r_bin_attr_tostring (flags, true);
                        if (flag_string) {
                                r_strbuf_append (buf, flag_string);
                        }
                        len -= strlen (flag_string);
                        if (len < 1) {
                                len = 1;
                        }
                        free (flag_string);
