R_API bool r_core_bin_rebase(RCore *core, ut64 baddr) {
        R_RETURN_VAL_IF_FAIL (core && core->bin, false);
        if (core->bin->cur && baddr != UT64_MAX) {
                RBinFile *bf = core->bin->cur;
                bf->bo->baddr = baddr;
                bf->bo->loadaddr = baddr;
                r_bin_object_set_items (bf, bf->bo);
                return true;
        }
        return false;
}
